import {markdown,content} from './viewer.js';
import {PROJECTS,TASKS,CRITERIA,FILES,QUESTIONS,STATE_LABELS,DEFAULT_STATE} from './data.js';
const root=document.getElementById('app'),KEY='yuanlei-u3-demo-v1';
let stored;try{stored=JSON.parse(sessionStorage.getItem(KEY)||'null')}catch{}
let state={...structuredClone(DEFAULT_STATE),...(stored||{})},route={},returns=state.returns||{},preview=null,feedback='',queueSelection='',queueFilter='all',queueProject='all',lastFocus=null;
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge=(text,tone='')=>`<span class="badge ${tone}">${e(text)}</span>`;
const btn=(label,action,attrs='',cls='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const key=(task,result)=>`${task.project}/${task.id}/${result.id}`;
const rs=(t,r)=>state.reviews[key(t,r)]?.status||r.status;
const ts=t=>state.taskStates[t.id]||t.state;
const tasks=()=>TASKS.filter(t=>t.project===route.project);
const pending=(all=false)=>TASKS.filter(t=>all||t.project===route.project).flatMap(t=>t.results.filter(r=>rs(t,r)==='pending').map(r=>({t,r})));
const save=()=>sessionStorage.setItem(KEY,JSON.stringify(state));
function event(name,extra={}){state.events.push({name,...extra});save()}
function parse(){const a=location.hash.replace(/^#/,'').split('/');return {mode:['a','b','c'].includes(a[0])?a[0]:'a',project:PROJECTS[a[1]]?a[1]:'alpha',page:a[2]||'overview',task:a[3]||'t1',result:a[4]||'r3'}}
function path(p={}){const v={...route,...p};return `#${v.mode}/${v.project}/${v.page}${v.page==='detail'?`/${v.task}/${v.result}`:''}`}
function go(p,{returning=false}={}){preview=null;feedback='';if(p.page==='detail'&&!returning)returns[`${p.project||route.project}/${p.task}`]={...route,full:state.full,scroll:window.scrollY};state.returns=returns;save();location.hash=path(p)}
function back(){const ret=returns[`${route.project}/${route.task}`];if(ret){state.full=ret.full;location.hash=path(ret);setTimeout(()=>window.scrollTo(0,ret.scroll),0)}else go({page:route.mode==='b'?'queue':'overview'},{returning:true})}
function readResult(){const t=TASKS.find(t=>t.id===route.task&&t.project===route.project);return {t,r:t?.results.find(r=>r.id===route.result)}}
function title(t){return state.scenario==='dense'?t.title+'：关于多个供应商年度覆盖、报价口径和交付风险的详细比较及当前办理依据':t.title}
function topbar(){return `<div class="prototypebar"><span class="mark">U3 · 合成数据 · 隔离可操作原型</span><select aria-label="原型方案" data-change="mode"><option value="a" ${route.mode==='a'?'selected':''}>A · 项目主方案</option><option value="b" ${route.mode==='b'?'selected':''}>B · 跨项目办理对照</option><option value="c" ${route.mode==='c'?'selected':''}>C · 观察与返回对照</option><option value="lab">R1 · 数据 / 导航 / 表达力</option></select><select aria-label="场景状态" data-change="scenario">${[['normal','正常'],['dense','长标题 / 密集'],['empty','空数据'],['loading','加载'],['error','读取失败'],['missing','文件失效'],['conflict','办理版本冲突']].map(([v,l])=>`<option value="${v}" ${state.scenario===v?'selected':''}>${l}</option>`).join('')}</select><span class="grow"></span>${btn(state.theme==='dark'?'☀ 浅色':'☾ 深色','theme','','small')}${btn('任务与范围','study','','small')}${btn('重置合成状态','reset','','small')}</div>`}
function sidebar(){const nav=route.mode==='b'?[['queue','⌂','我的处理']]:[['overview','▦','概览'],['workbench','◈','工作台'],['tasks','☷','工作'],['agents','◇','智能体'],['files','▤','资料']];return `<aside class="sidebar"><div class="brand">元垒<small>YUANLEI</small></div><select class="project-select" aria-label="当前项目" data-change="project">${Object.entries(PROJECTS).map(([id,p])=>`<option value="${id}" ${id===route.project?'selected':''}>${p.name} · ${id==='alpha'?'A':'B'}</option>`).join('')}</select><div class="project-tag">${e(PROJECTS[route.project].tag)}</div><nav class="navlist">${nav.map(([page,icon,label])=>`<button class="nav-button ${route.page===page||(page==='overview'&&['business','detail','maintenance'].includes(route.page))?'active':''}" data-action="nav" data-page="${page}" ${route.page===page?'aria-current="page"':''}><span class="icon">${icon}</span>${label}</button>`).join('')}<div class="nav-divider"></div><button class="nav-button" data-action="inbox"><span class="icon">◌</span>跨项目收件箱 ${badge('2')}</button></nav><div class="sidebar-foot">个人项目 · 标签分类<br>所有数据与办理均为模拟<br>未连接元垒业务接口</div></aside>`}
function heading(name,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${e(PROJECTS[route.project].name)} / ${route.mode==='c'?'观察工作区':'项目概览'}</div><h1>${e(name)}</h1><div class="subtext">${desc}</div></div><div class="actions">${actions}</div></div>`}
function tabs(page){return `<div class="tabs" aria-label="概览类型"><button data-action="nav" data-page="overview" class="${page==='overview'?'active':''}" ${page==='overview'?'aria-current="page"':''}>管理概览</button><button data-action="nav" data-page="business" class="${page==='business'?'active':''}" ${page==='business'?'aria-current="page"':''}>业务 · 采购观察</button></div>`}
function special(){if(state.scenario==='loading')return `<div class="panel panel-pad" aria-busy="true"><p class="muted">正在读取合成场景…平台入口继续可达。</p>${Array.from({length:4},()=>'<div class="skeleton"></div>').join('')}${btn('结束加载','normal')}</div>`;if(state.scenario==='error')return `<div class="notice error" role="alert">合成读取失败。原入口继续可用，不能把失败当作暂无数据。${btn('重新读取','normal','','small')}</div>`;if(state.scenario==='empty')return `<div class="panel empty"><div>◈</div><h2>项目尚无正式工作或交付</h2><p>从一件人工独立事项开始；无需先建议题或配置智能体。</p>${btn('新建独立工作','create','','primary')} ${btn('恢复合成样本','normal')}</div>`;return ''}
function manage(){const pts=pending(),list=tasks(),specialState=special(),isAlpha=route.project==='alpha';return heading('管理概览','先看需要关注的事，再进入准确对象办理。',btn('刷新','refresh')+btn('Dashboard 维护','nav','data-page="maintenance"')+btn('新建工作','create','','primary'))+tabs('overview')+`<div class="notice"><span>统计读取：2026-10-08 10:30 +08:00</span><span class="grow"></span><span>逾期口径：UTC · 合成样本</span></div>`+(specialState||`<div class="grid4"><section class="panel metric"><div class="label"><span class="dot"></span>待治理</div><a class="value-link" href="${path({page:'workbench'})}"><div class="value">${isAlpha?3:0}<small>项</small></div></a><div class="foot">${isAlpha?'议题 1 · 决策 1 · 工作建议 1':'尚无治理来源 · 可直接人工工作'}</div></section><section class="panel metric"><div class="label">正式工作</div><a class="value-link" href="${path({page:'tasks'})}"><div class="value">${list.length}<small>项</small></div></a><div class="foot">已完成 ${list.filter(t=>ts(t)==='done').length} · 受阻 ${list.filter(t=>ts(t)==='blocked').length}</div></section><section class="panel metric"><div class="label">待验收</div><div class="value">${pts.length}<small>份 / ${new Set(pts.map(x=>x.t.id)).size} 项工作</small></div><div class="foot">结果与工作分别计数</div></section><section class="panel metric"><div class="label">当前执行异常</div><a class="value-link" href="${path({page:'agents'})}"><div class="value">${isAlpha?1:0}<small>次最新尝试</small></div></a><div class="foot">${isAlpha?'历史异常 2 · 按需查看':'答复等待与异常分别呈现'}</div></section></div><div class="layout2"><div class="stack"><section class="panel"><div class="panel-head"><h2>待验收交付</h2>${badge(`${pts.length} 份结果`,'warn')}</div>${pts.length?pts.map(({t,r})=>resultRow(t,r)).join(''):`<div class="empty">当前待验收为零。已接受结果仍可在工作详情查看。</div>`}<div class="section-footer"><span>按准确结果定位，保留提交时要求</span><a href="${path({page:'tasks'})}">所有工作 →</a></div></section><section class="panel"><div class="panel-head"><h2>当前风险与介入</h2><a href="${path({page:'agents'})}">查看执行 →</a></div><div class="row"><div class="content"><div class="title">${isAlpha?'第三年度资料来源尚需补充':'已有答复，仍需观察恢复'}</div><div class="desc">${isAlpha?'CG-014 · 执行 E5 · 处理者：资料智能体上级':'Q2 · 展陈执行 B3 · 处理者：展陈智能体'}<br>执行异常与需要人答复分别呈现。</div><div class="meta">${badge(isAlpha?'上级处理中':'已答复 · 未恢复','warn')}${badge('未计入人的待办')}</div></div></div></section></div><div class="stack"><section class="panel panel-pad"><h2>工作进展</h2>${['todo','doing','blocked','done','cancelled'].map(s=>`<a href="${path({page:'tasks'})}" class="state-count"><span>${STATE_LABELS[s]}</span><span class="tabular">${list.filter(t=>ts(t)===s).length}</span></a>`).join('')}<div class="small-note">工作进行、运行成功与交付验收是三种状态。</div></section><section class="panel panel-pad"><h2>当前依据</h2><p class="subtext">${isAlpha?'蓝图：采购资料可信与按期交付':'人工独立事项 · 尚无治理来源'}</p><div class="more-tile"><div class="mini-title">${isAlpha?'有效决策 D-03 · v2':'独立工作依据'}</div><strong>${isAlpha?'统一含税报价，覆盖三个年度':'项目 B 的绑定与工作独立'}</strong><p class="subtext">正式工作保留采用版本，历史要求不被覆盖。</p><a href="${path({page:'workbench'})}">查看议题与决策 →</a></div><details><summary>关系、历史异常与汇报</summary><p>${isAlpha?'蓝图 → 议题 I-02 → 决策 D-03 v2 → CG-012 → R3<br>历史执行 E1/E2 保留，最新状态不会改写旧记录。关系图与历史在本轮用摘要模拟。':'人工独立创建 → ZC-004 → B-R1。该项目尚无蓝图、议题或决策样本。'}</p></details></section></div></div>`)}
function resultRow(t,r){return `<div class="row"><div class="content"><div class="mini-title">${e(t.code)} · ${e(r.id.toUpperCase())}</div><a class="title" href="${path({page:'detail',task:t.id,result:r.id,project:t.project})}" data-origin="result">${e(title(t))}</a><div class="desc">${e(r.summary)}</div><div class="meta">${badge(r.revision===t.criteria?`当前要求 v${r.revision}`:`旧要求 v${r.revision}` ,r.revision===t.criteria?'good':'warn')}<span class="muted">${e(r.time)}</span></div></div>${btn('进入办理','open','data-task="'+t.id+'" data-result="'+r.id+'" data-project="'+t.project+'"','small')}</div>`}
function taskList(){const list=tasks().filter(t=>state.filter==='all'||ts(t)===state.filter);return heading('正式工作','人工独立事项、决策派生工作与智能体执行共用正式工作身份。',btn('新建工作','create','','primary'))+`<div class="chips">${['all','todo','doing','blocked','done'].map(s=>`<button class="chip ${state.filter===s?'active':''}" data-action="filter" data-value="${s}">${s==='all'?'全部工作':STATE_LABELS[s]}</button>`).join('')}</div><div class="panel table-wrap"><table class="compact-table"><thead><tr><th>工作</th><th>工作状态</th><th>交付 / 执行</th><th>责任与时间</th></tr></thead><tbody>${list.map(t=>`<tr><td><div class="mini-title">${e(t.code)}</div><a href="${path({page:'detail',task:t.id,result:t.results.find(r=>rs(t,r)==='pending')?.id||t.results[0]?.id||'none'})}">${e(title(t))}</a></td><td>${badge(STATE_LABELS[ts(t)],ts(t)==='blocked'?'warn':'')}</td><td>${t.results.filter(r=>rs(t,r)==='pending').length} 份待验收<br><span class="muted">${t.id==='t1'?'E1 失败 · 无正式结果':t.results.length?'有交付依据':'无正式结果'}</span></td><td>${e(t.owner)}<br><span class="muted">${e(t.due)}</span></td></tr>`).join('')}</tbody></table>${!list.length?'<div class="empty">此筛选暂无工作</div>':''}</div>`}
function criteriaLines(revision){return state.scenario==='dense'?[...CRITERIA[revision],...Array.from({length:8},(_,i)=>`补充合成检验 ${i+1}：逐项核对来源名称、数据取得时间、年度覆盖、可访问证据与例外说明。长条件用于检查阅读密度和返回办理。`)]:CRITERIA[revision]}
function detail(t,r,queue=false){if(!t)return `<section class="panel empty"><h2>对象已失效或不在当前项目</h2>${btn('回管理概览','nav','data-page="overview"')}</section>`;const status=r?rs(t,r):'',draft=r?state.drafts[key(t,r)]||'':'',review=r?state.reviews[key(t,r)]:null;return `<div class="detail-identity"><div class="eyebrow">${queue?'跨项目我的处理':e(PROJECTS[t.project].name)} / ${e(t.code)} / ${r?e(r.id.toUpperCase()):'工作'}</div><div class="actions">${btn(queue?'← 返回处理列表':'← 返回'+(returns[`${t.project}/${t.id}`]?.page==='business'?'采购观察':'来源页面'),queue?'queueback':'back','','quiet small return-btn')}${badge(PROJECTS[t.project].name)}${badge(STATE_LABELS[ts(t)])}</div><h1>${e(title(t))}</h1><div class="actions">${badge(r?`${r.id.toUpperCase()} · ${STATE_LABELS[status]}`:'暂无结果',status==='accepted'?'good':'warn')}<span class="subtext">${r?e(r.attempt)+' · '+e(r.time):'可独立人工交付'}</span></div>${r?`<div class="actions" style="margin-top:10px"><label for="result-picker" class="subtext">选中结果</label><select id="result-picker" class="btn small" aria-label="选中结果" data-change="result">${t.results.map(x=>`<option value="${x.id}" ${r.id===x.id?'selected':''}>${x.id.toUpperCase()} · ${STATE_LABELS[rs(t,x)]} · 要求 v${x.revision}</option>`).join('')}</select>${status==='pending'?btn('到办理意见 ↓','focus-review','','quiet small'):''}</div>`:''}</div>${['error','loading'].includes(state.scenario)?`<div class="notice ${state.scenario==='error'?'error':''}" role="status">${state.scenario==='error'?'结果重新读取失败（模拟）；上次参考内容保留，办理暂不可提交。':'正在重新读取结果（模拟）；意见草稿保持，办理暂不可提交。'} ${btn('重新读取','normal','','small')}</div>`:''}${feedback?`<div class="notice ${feedback.startsWith('已')?'info':'error'}" role="alert">${e(feedback)}</div>`:''}<div class="detail-grid"><div class="stack"><section class="panel"><div class="panel-pad"><div class="mini-title">${r?'选中结果摘要':'工作要求'}</div><p class="summary-text">${r?e(r.summary):'此人工事项无需先建议题或指定智能体。交付表单的真实上传与持久化不在本轮实现范围。'}</p>${r?`<div class="actions">${badge(`提交依据 v${r.revision}`,r.revision===t.criteria?'good':'warn')}${badge(`当前要求 v${t.criteria}`)}</div>${r.revision!==t.criteria?'<div class="notice warn" style="margin-top:15px">该结果按旧要求提交。可以核对旧依据；接受需补交当前要求下的新结果。</div>':''}<h3 style="margin-top:21px">验收条件</h3><div class="subtext">${e(CRITERIA[r.revision][0])}</div><details><summary>查看提交时完整条件（v${r.revision}）</summary><ul class="criteria">${criteriaLines(r.revision).map(c=>`<li>${e(c)}</li>`).join('')}</ul></details>${r.revision!==t.criteria?`<details><summary>对照当前要求 v${t.criteria} 的变化</summary><div class="compare-line"><div><h3>提交时 v${r.revision}</h3><p>${e(CRITERIA[r.revision][1])}</p></div><div class="changed"><h3>当前 v${t.criteria}</h3><p>${e(CRITERIA[t.criteria][1])}</p></div></div><p>旧依据保留，接受以当前业务契约为准。</p></details>`:''}<h3 style="margin-top:24px">交付文件 <span class="muted">${r.files.length} 份</span></h3>${r.files.map(fid=>fileRow(t,r,fid)).join('')}`:`${btn('查看原型能力范围','scope')}`}</div>${r?`<div class="review-panel"><label class="field-label" for="review-${r.id}">办理意见</label><textarea id="review-${r.id}" data-draft="${key(t,r)}" placeholder="填写本次结果的核对依据或未接受原因" ${status!=='pending'?'readonly':''}>${e(draft||review?.comment||'')}</textarea><div class="draft-status" data-draftstatus>${draft?'意见草稿已保留':'草稿按项目 / 工作 / 结果分别保存'} · 当前 ${e(r.id.toUpperCase())}</div>${status==='pending'?`<div class="actions">${btn('未接受','review','data-status="not_accepted"','danger')}${btn('接受结果','review','data-status="accepted"')}${btn('接受并完成工作','review','data-status="accepted" data-complete="1"','primary')}</div>`:`<div class="notice info">${e(STATE_LABELS[status])} · 模拟回读状态；${review?.complete?'工作已完成':'结果历史保留'}</div>`}<div class="small-note">本页办理只改变隔离原型的本地状态。真实版本/权限/证据校验尚未连接。</div></div>`:''}</section><section class="panel panel-pad"><details style="border:0;margin:0;padding:0"><summary>当前采用依据、历史与设置</summary><p>${e(t.source||'未提供治理来源样本')}<br>${t.id==='t1'?'蓝图 → 议题 I-02 → 决策 D-03 v2 → CG-012。':'来源关联以本工作样本为准。'}来源关系仅为合成导航说明。</p><p>${t.failedAttempts?.length?e(t.failedAttempts.join('；')):'本工作未提供失败尝试样本。'}失败尝试不能作为待验收交付。<br>要求编辑、责任人设置、真实委派与上传尚未实现。</p></details></section></div><aside class="stack"><section class="panel"><div class="panel-head"><h2>结果与尝试</h2>${badge(t.results.length+' 份')}</div>${t.results.map(x=>`<button class="result-item ${r?.id===x.id?'active':''}" data-action="select-result" data-result="${x.id}" data-task="${t.id}" data-project="${t.project}"><strong>${e(x.id.toUpperCase())} · ${e(STATE_LABELS[rs(t,x)])}</strong>${badge('要求 v'+x.revision,x.revision===t.criteria?'good':'warn')}<div class="desc">${e(x.attempt)}<br>${e(x.time)}</div></button>`).join('')}<details class="panel-pad" style="margin:0"><summary>无正式结果的尝试</summary><p>${t.failedAttempts?.length?e(t.failedAttempts.join('；')):'本工作未提供失败尝试样本。'}<br>失败原因保留，未产生可验收交付。</p></details></section><section class="panel panel-pad"><h3>当前办理身份</h3><div class="subtext">项目：${e(PROJECTS[t.project].name)}<br>工作：${e(t.code)}<br>结果：${r?e(r.id.toUpperCase()):'无'}<br>当前要求：v${t.criteria}</div><div class="small-note">同标题在另一项目有独立工作。项目、工作、结果共同确认身份。</div></section></aside></div>`}
function fileRow(t,r,fid){const f=FILES[fid],missing=state.scenario==='missing'&&fid==='comparison';return `<div class="file-row"><span class="file-icon">${f.type.toUpperCase()}</span><div class="file-title">${e(f.name)}<small>${e(f.size)} · ${missing?'引用已失效（模拟）':'可读取（合成内容）'}</small></div>${btn('快速查看','preview',`data-file="${fid}" data-task="${t.id}" data-result="${r.id}" data-project="${t.project}"`,'small')}<a class="btn small" href="file.html?project=${t.project}&task=${t.id}&result=${r.id}&file=${fid}&missing=${missing?1:0}" target="_blank" rel="noopener">独立打开 ↗</a></div>`}
function supplierRows(project,period){const totals={alpha:{'07':[100000,90000,92000,4000],'08':[110000,98000,109000,4000],'09':[120000,108000,116000,4000]},beta:{'08':[46000,42000,50000,4000],'09':[62000,58000,62000,4000]}};const values=totals[project][period];return values?values.map((v,i)=>`<tr><td>${i===3?'配套费用':(project==='alpha'?'采购供应商':'展具供应商')+['甲','乙','丙'][i]}</td><td>${v.toLocaleString('zh-CN')}</td><td>${i===3?'单列费用':'合成来源'}</td></tr>`).join(''):'<tr><td colspan="3">该月未取得数据；没有借用另一个项目的数值。</td></tr>'}
function business(){const p=route.project,amount=p==='alpha'?348000:186000,base=p==='alpha'?[286000,321000,348000]:[null,142000,186000],pts=pending();return heading('采购观察','项目业务数据与管理口径分别说明；所有数值均为合成。',btn(state.full?'退出全屏 · 返回观察':'全屏观察','full')+btn('维护与绑定','nav','data-page="maintenance"'))+tabs('business')+`<div class="actions" style="margin-bottom:17px"><label class="subtext" for="period">观察月份</label><select id="period" class="btn" data-change="period">${['07','08','09'].map(v=>`<option value="${v}" ${state.businessPeriod===v?'selected':''}>2026 年 ${v} 月</option>`).join('')}</select>${badge('含税 · 元')}${badge('Asia/Shanghai')}${btn('刷新数据','refresh','','small')}</div>`+(state.scenario==='loading'?special():`<div class="notice ${state.scenario==='error'?'error':'warn'}" role="status">${state.scenario==='error'?'供应商源读取失败；采购金额保留上次快照。管理概览继续可达。':'采购月表为旧快照；同比基期'+(p==='beta'?'缺失，不能按 0 计算。':'已提供。')+'读取时间与数据截至时间分别显示。'}</div><div class="grid4"><section class="panel metric"><div class="label">${state.businessPeriod} 月采购金额</div><div class="value">${state.scenario==='empty'||base[Number(state.businessPeriod)-7]===null?'—':(base[Number(state.businessPeriod)-7]/10000).toFixed(1)}<small>万元</small></div><div class="foot">${state.scenario==='empty'?'未接入 · 非零金额':p==='beta'&&state.businessPeriod==='07'?'缺数 · 非零金额':'源：合成采购月表 '+(p==='alpha'?'A':'B')}</div></section><section class="panel metric"><div class="label">同比变化</div><div class="value">${p==='beta'||state.scenario==='empty'?'—':'+8.2'}<small>${p==='beta'?'缺基期':'%'}</small></div><div class="foot">${p==='beta'?'不把缺数按零计算':'示例口径 · 同月对比'}</div></section><section class="panel metric"><div class="label">管理待验收</div><div class="value">${pts.length}<small>份</small></div><div class="foot">源：合成正式结果 · 独立于采购月表</div></section><section class="panel metric"><div class="label">数据健康</div><div class="value">${(p==='alpha'?1:2)+(state.scenario==='error'?1:0)}<small>项数据提示</small></div><div class="foot">过期 / 缺数分别标注</div></section></div><div class="screen-grid"><section class="panel"><div class="panel-head"><h2>月度采购金额</h2><span class="subtext">点击柱形查看该月明细</span></div><div class="chart-wrap"><div class="bar-chart">${(state.scenario==='empty'?[null,null,null]:base).map((v,i)=>`<div class="bar-column"><span class="bar-value">${v===null?'缺数':(v/10000).toFixed(1)+' 万'}</span>${v===null?'<div class="more-tile" style="height:55px;margin:0">未提供</div>':`<button data-action="drill" data-period="${String(i+7).padStart(2,'0')}" style="height:${v/6000}px" aria-label="查看 ${i+7} 月采购明细"></button>`}<span class="bar-label">${i+7} 月</span></div>`).join('')}</div></div><div class="data-strip"><span>数据截至 2026-09-30 23:59 +08:00<br>读取于 2026-10-08 10:30 +08:00</span><span>来源：合成采购月表 ${p==='alpha'?'A':'B'}<br>显示的是数据快照，刷新未改变源日期。</span></div></section><section class="panel"><div class="panel-head"><h2>交付关注</h2><a href="${path({page:'overview'})}">管理概览 →</a></div>${pts.slice(-2).map(({t,r})=>resultRow(t,r)).join('')||'<div class="empty">当前无待验收</div>'}<div class="data-strip">此区按正式结果状态派生，与采购金额的刷新时间独立。</div></section><section class="panel panel-pad"><details style="border:0;margin:0;padding:0"><summary>供应商结构与明细 · 按需展开</summary><div class="table-wrap"><table class="compact-table"><thead><tr><th>供应商</th><th>含税金额</th><th>备注</th></tr></thead><tbody>${state.scenario==='empty'?'<tr><td colspan="3">未接入</td></tr>':supplierRows(p,state.businessPeriod)}</tbody></table></div></details></section><section class="panel panel-pad"><h2>口径与来源</h2><p class="subtext">金额：含税、人民币元。趋势覆盖 7—9 月。读取成功不证明数据最新；缺数、过期和读取失败分别呈现。</p><details><summary>指标定义与当前绑定</summary><p>项目 ${e(PROJECTS[p].name)} → 月表 ${p.toUpperCase()}。另一个项目使用独立月表，不继承本项目数值。真实连接、权限和数据更新服务尚未实现。</p></details><a href="lab.html?project=${p}">进入独立 R1 数据 / 导航样例 →</a></section></div>`)}
function workbench(){if(route.project==='beta')return heading('项目工作台','示例 B 尚无治理来源，人工事项仍可直接开始。',btn('新建独立工作','create','','primary'))+'<section class="panel empty">本项目未提供蓝图、议题与决策合成样本。</section>';return heading('项目工作台','从研讨到正式执行；人工事项仍有直接入口。',btn('新建独立工作','create','','primary'))+`<div class="layout2"><section class="panel panel-pad"><h2>当前蓝图</h2><p class="summary-text">采购资料可信、依据明确、按期交付</p><div class="row"><div class="content"><div class="mini-title">议题 I-02</div><strong>报价与年度覆盖口径</strong><div class="desc">已形成正式决策。讨论记录、来源与版本在真实产品中由治理 Owner 管理。</div></div></div><div class="more-tile"><div class="mini-title">有效决策 D-03 · v2</div><h3>统一含税报价，覆盖三个年度</h3><p class="subtext">v1：两个年度 → v2：三个年度。旧要求结果保留对照。</p>${btn('查看对应工作','open','data-task="t1" data-result="r3" data-project="alpha"')}</div></section><section class="panel panel-pad"><h2>待治理 · 3 项</h2><p class="subtext">议题 1 · 决策草稿 1 · 工作建议 1</p><div class="notice">本切片解释职责与来源。准入、批准、真实转工作均未实现。</div>${btn('查看全部正式工作','nav','data-page="tasks"')}</section></div>`}
function agents(){if(route.project==='beta')return heading('智能体执行','示例 B 的答复与恢复入口。')+'<section class="panel panel-pad"><h2>需要人介入</h2><p>Q1 已读未答，Q2 已答复未恢复；执行状态与处理者见跨项目收件箱。</p>'+btn('到跨项目收件箱','inbox','','primary')+'</section>';return heading('智能体执行','接收工作、运行状态、交付验收与问题处理者分别呈现。')+`<div class="layout2"><section class="panel panel-pad"><h2>资料智能体 · 当前执行 E5</h2><p class="summary-text">补齐第三年度来源</p>${badge('执行受阻','warn')} ${badge('处理者：直接上级')}<p class="subtext">已接收 CG-014，当前执行失败；没有正式结果。上级处理中尚未成为人的待答复。</p><details><summary>尝试与求助链（模拟）</summary><p>E1：失败，无结果。E5：缺来源 → 直接上级处理。远端问题 ID、送达、采用、恢复与 lease 未连接。</p></details></section><section class="panel panel-pad"><h2>需要人介入 · 示例 B</h2><p class="subtext">Q1 已读但未答复。Q2 已答复但未恢复，入口继续保留。</p>${btn('到跨项目收件箱','inbox','','primary')}<p class="small-note">执行配置、取消与恢复不在本轮实现范围。</p></section></div>`}
function maintenance(){return heading('Dashboard 维护','当前启用、草稿与数据更新分别解释；仅模拟版本与绑定。',btn('返回业务观察','nav','data-page="business"'))+`<div class="grid4"><section class="panel metric"><div class="label">当前启用</div><div class="value">v1</div><div class="foot">采购观察 · 稳定版本</div></section><section class="panel metric"><div class="label">模板来源</div><div class="value" style="font-size:24px">采购观察 v1</div><div class="foot">同人复用结构，不携带项目数据</div></section><section class="panel metric"><div class="label">项目绑定</div><div class="value" style="font-size:24px">月表 ${route.project==='alpha'?'A':'B'}</div><div class="foot">当前项目独立输入</div></section><section class="panel metric"><div class="label">草稿状态</div><div class="value" style="font-size:24px">待验证</div><div class="foot">不会覆盖当前启用版</div></section></div><section class="panel panel-pad"><h2>本轮能力边界</h2><p class="subtext">模板升级、智能体草稿、竞争更新、发布许可及回退这里只展示概念，没有实现真实工具或持久协议。本轮有限 R1 样例单独验证项目绑定、数据与准确对象导航，并用空间巡看要求检验表达力。</p><a class="btn primary" href="lab.html?project=${route.project}">操作独立 R1 样例 →</a></section>`}
function queueItems(){return [...pending(true).map(({t,r})=>({id:`${t.id}:${r.id}`,project:t.project,kind:'result',t,r,title:t.title,stage:'pending',read:state.read[`res:${r.id}`]||false})),...QUESTIONS.map(q=>({...q,kind:'question',stage:state.answers[q.id]?'answered_unresumed':q.stage,read:state.read[q.id]??q.read}))].filter(x=>(queueProject==='all'||x.project===queueProject)&&(queueFilter==='all'||x.stage===queueFilter))}
function queueHistory(){const [tid,rid]=queueSelection.split(':');const t=TASKS.find(x=>x.id===tid),r=t?.results.find(x=>x.id===rid);return r?{t,r,kind:'result',project:t.project}:null}
function queue(){const items=queueItems(),selected=items.find(x=>x.id===queueSelection)||queueHistory();return heading('我的处理','业务处理阶段为主，阅读状态独立；这是 B 的高频办理对照切片。',btn('查看同任务说明','study'))+`<div class="notice info">对照任务：核对 A 的 R2 旧要求，再办理 A 的 R3 与 B 的 B-R1。同标题请先确认项目。Q1 已读未答、Q2 已答未恢复不会因阅读消失。</div><div class="actions" style="margin-bottom:14px"><select class="btn" data-change="queueproject" aria-label="队列项目筛选"><option value="all">全部项目</option>${Object.entries(PROJECTS).map(([p,v])=>`<option value="${p}" ${queueProject===p?'selected':''}>${e(v.name)}</option>`).join('')}</select>${['all','pending','needs_answer','answered_unresumed'].map(v=>`<button class="chip ${queueFilter===v?'active':''}" data-action="queuefilter" data-value="${v}">${v==='all'?'全部业务事项':STATE_LABELS[v]}</button>`).join('')}</div><div class="queue-grid ${selected?'selected':''}"><section class="panel queue-list"><div class="panel-head"><h2>处理列表</h2>${badge(items.length+' 项')}</div>${items.map(x=>`<button class="queue-row ${x.id===queueSelection?'active':''}" data-action="queuepick" data-id="${x.id}"><div class="actions">${badge(PROJECTS[x.project].name)}${badge(x.read?'已读':'未读')}</div><div class="q-title">${e(x.title)}</div><small>${x.kind==='result'?`${e(x.t.code)} · ${e(x.r.id.toUpperCase())} · 要求 v${x.r.revision}`:`${e(x.id.toUpperCase())} · 处理者 ${e(x.handler)}`}</small><div class="meta" style="margin-top:9px">${badge(STATE_LABELS[x.stage],x.stage==='pending'?'warn':'')}</div></button>`).join('')||'<div class="empty">此业务阶段没有事项。<br>已处理状态保留在原工作历史。</div>'}</section><section>${selected?selected.kind==='result'?detail(selected.t,selected.r,true):question(selected):'<div class="panel empty empty-detail"><h2>选择一项开始核对</h2><p>项目、工作、结果/问题身份在详情持续可见。</p></div>'}</section></div>`}
function question(q){return `<div class="panel panel-pad">${btn('← 返回处理列表','queueback','','quiet small')}<div class="eyebrow" style="margin-top:15px">${e(PROJECTS[q.project].name)} / ${e(q.id.toUpperCase())} / ${e(q.attempt)}</div><h2>${e(q.title)}</h2><p class="subtext">${STATE_LABELS[q.stage]} · 当前处理者 ${e(q.handler)}</p>${badge(q.read?'已读':'未读')} ${btn(q.read?'标为未读':'标为已读','markread',`data-id="${q.id}" data-read="${q.read?0:1}"`,'small')}<div class="notice warn" style="margin-top:18px">问题、答复和恢复均为本地模拟。提交答复不把问题标为已恢复。</div><label class="field-label" for="answer">答复意见</label><textarea id="answer" data-answer="${q.id}" ${q.stage==='answered_unresumed'?'readonly':''}>${e(state.drafts['q:'+q.id]||state.answers[q.id]||q.answer||'')}</textarea>${q.stage==='needs_answer'?btn('提交模拟答复','answer',`data-id="${q.id}"`,'primary'):'<p class="subtext">答复已记录，等待执行方确认采用与恢复。入口保留。</p>'}</div>`}
function render(){route=parse();const {t,r}=readResult();if(route.mode==='b')route.page='queue';const full=state.full&&route.page==='business';document.body.dataset.theme=state.theme;document.body.classList.toggle('full-screen',full);root.innerHTML=topbar()+`<div class="app-shell">${sidebar()}<main class="main ${route.page==='business'?'business-page':''}">${route.page==='detail'?detail(t,r):route.page==='tasks'?taskList():route.page==='business'?business():route.page==='workbench'?workbench():route.page==='agents'?agents():route.page==='maintenance'?maintenance():route.page==='queue'?queue():route.page==='files'?heading('项目资料','资料与结果证据不同；本轮只提供结果中的合成文件。')+'<section class="panel empty">从准确结果打开其交付文件，保留办理身份。'+btn('查看当前结果文件','open',route.project==='alpha'?'data-task="t1" data-result="r3" data-project="alpha"':'data-task="b1" data-result="b-r1" data-project="beta"')+'</section>':manage()}</main></div>`+(preview?overlay():'');if(preview)root.querySelector('[data-action="close"]')?.focus()}
function overlay(){const {kind}=preview;let name='',body='',foot='';if(kind==='file'){const {fid,t,r}=preview,f=FILES[fid];name=f.name;const missing=state.scenario==='missing'&&fid==='comparison';body=`<div class="notice">${e(PROJECTS[t.project].name)} / ${e(t.code)} / ${e(r.id.toUpperCase())} · 合成文件。路径可读不证明历史内容不变。</div>${missing?'<div class="notice error" role="alert">文件引用已失效（模拟）。保留办理意见，需核对新的可访问证据。</div>':f.type==='image'?`<img src="${f.url}" alt="三家供应商含税报价对照（合成）">`:f.type==='pdf'?`<div class="notice warn">12 页阅读空间模拟，未接 PDF 引擎。可独立打开合成 PDF 文件。</div><h3>采购核对册 · 第 ${preview.pdfPage||1} 页</h3><p>含税报价 / 三个年度来源 / 风险核对（合成内容）</p>${btn('上一页','pdfprev','','small')}${btn('下一页','pdfnext','','small')}`:markdown(content(fid,r))}`;foot=`${btn('关闭 · 返回此结果','close')}<a class="btn" href="file.html?project=${t.project}&task=${t.id}&result=${r.id}&file=${fid}&missing=${missing?1:0}" target="_blank" rel="noopener">独立打开 ↗</a>`}else if(kind==='drill'){name=`2026 年 ${state.businessPeriod} 月采购明细`;body=`<div class="notice">当前项目 ${e(PROJECTS[route.project].name)} · 含税人民币元 · 合成月表</div><table class="compact-table"><thead><tr><th>供应商</th><th>金额</th><th>来源</th></tr></thead><tbody>${supplierRows(route.project,state.businessPeriod)}</tbody></table><p class="subtext">明细读取和对象跳转是两种钻取。关闭回原月份、项目与全屏状态。</p>`;foot=btn('返回采购观察','close')}else if(kind==='create'){name='新建人工独立工作';body='<div class="notice info">直接创建，无需议题或智能体。这里只演示入口与表单，不写正式工作。</div><label class="field-label" for="newtitle">工作标题</label><input id="newtitle" type="text" value="核对采购凭据"><label class="field-label" for="newcriteria" style="margin-top:20px">验收条件</label><textarea id="newcriteria">金额、来源与凭据可以相互核对。</textarea><p class="subtext">项目编号 CG 已配置；首次设置可在真实创建入口内提示。</p>';foot=btn('关闭原型表单','close')+btn('模拟创建','fakecreate','','primary')}else{name=kind==='study'?'共同任务与原型范围':'本轮能力范围';body=`<div class="study"><div class="notice info">同一批合成数据贯穿 A / B / C。本地状态共用；公平复跑每套前重置一次。</div>${['A：管理概览 → R2 旧依据对照 → R3 核对文件并填写意见 → 接受完成 → 回原概览。','B：同样核对 R2 / R3，再连续办理另一项目同标题 B-R1；另找已读未答与已答未恢复。','C：采购观察选择 9 月 → 全屏 → 进入 R3 → 看文件 → 回同月份全屏 → 退出。','R1：切换两项目独立数据，刷新/失败/空数据、准确导航与越界拒绝；用空间巡看要求测试表达力。'].map((s,i)=>`<div class="step"><span class="num">${i+1}</span><span>${e(s)}</span></div>`).join('')}<p>已实现：页面与返回、主题/窄屏、本地意见草稿、文件查看切片、模拟办理/阅读/答复状态。未实现：真实认证、上传、数据库、Agent、远端恢复、模板发布、真实 PDF 引擎。R1 独立使用本地合成 HTTP 和现有 Vue 运行时。</p></div>`;foot=btn('开始操作','close')+`<a class="btn" href="lab.html?project=${route.project}">R1 技术样例 →</a>`}return `<div class="overlay"><section class="drawer" role="dialog" aria-modal="true" aria-label="${e(name)}"><div class="drawer-head"><div><h2>${e(name)}</h2><div class="subtext">U3 · 隔离合成原型</div></div>${btn('✕','close','aria-label="关闭查看"','quiet')}</div><div class="drawer-body">${body}</div><div class="drawer-foot">${foot}</div></section></div>`}
function restoreFocus(){if(!lastFocus?.dataset.action)return;const action=lastFocus.dataset.action,file=lastFocus.dataset.file;root.querySelector(`[data-action="${action}"]${file?`[data-file="${file}"]`:''}`)?.focus()}
function toast(text){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.role='status';el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),3200)}
function current(){if(route.mode==='b'){const x=queueItems().find(x=>x.id===queueSelection)||queueHistory();return x?.kind==='result'?{t:x.t,r:x.r}:{};}return readResult()}
root.addEventListener('input',ev=>{if(ev.target.dataset.draft){state.drafts[ev.target.dataset.draft]=ev.target.value;save();root.querySelector('[data-draftstatus]').textContent='意见草稿已保留 · 按当前结果独立保存'}if(ev.target.dataset.answer){state.drafts['q:'+ev.target.dataset.answer]=ev.target.value;save()}});
root.addEventListener('change',ev=>{const a=ev.target.dataset.change,v=ev.target.value;if(a==='mode'){if(v==='lab'){location.href='lab.html?project='+route.project;return}queueSelection='';go({mode:v,page:v==='b'?'queue':v==='c'?'business':'overview'})}if(a==='project'){queueSelection='';go({project:v,page:route.mode==='b'?'queue':route.mode==='c'?'business':'overview'})}if(a==='scenario'){state.scenario=v;save();render()}if(a==='result'){const {t}=current();if(route.mode==='b'){queueSelection=t.id+':'+v;feedback='';render()}else go({page:'detail',result:v},{returning:true})}if(a==='period'){state.businessPeriod=v;save();event('period',{value:v});render()}if(a==='queueproject'){queueProject=v;queueSelection='';render()}});
root.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(!el){const a=ev.target.closest('a');if(a?.getAttribute('href')?.startsWith('#')&&a.hash.includes('/detail/')&&route.page!=='detail'){const parts=a.hash.slice(1).split('/');returns[`${parts[1]}/${parts[3]}`]={...route,full:state.full,scroll:window.scrollY};state.returns=returns;save()}return}const a=el.dataset.action;
 if(a==='nav')go({page:el.dataset.page});if(a==='open'){event('open',{mode:route.mode,project:el.dataset.project,task:el.dataset.task,result:el.dataset.result});go({page:'detail',project:el.dataset.project,task:el.dataset.task,result:el.dataset.result})}
 if(a==='focus-review')root.querySelector('[data-draft]')?.focus();if(a==='back')back();if(a==='theme'){state.theme=state.theme==='light'?'dark':'light';save();render()}
 if(a==='reset'){sessionStorage.removeItem(KEY);state=structuredClone(DEFAULT_STATE);queueSelection='';queueFilter='all';feedback='';preview=null;returns={};render();toast('合成状态已重置；没有改动真实业务')}
 if(a==='normal'){state.scenario='normal';save();render()}if(a==='refresh'){event('refresh',{page:route.page});toast('合成快照已重新读取；源数据截至时间不变')}
 if(a==='filter'){state.filter=el.dataset.value;save();render()}
 if(a==='select-result'){feedback='';if(route.mode==='b'){queueSelection=el.dataset.task+':'+el.dataset.result;render()}else go({page:'detail',task:el.dataset.task,result:el.dataset.result,project:el.dataset.project},{returning:true})}
 if(['preview','study','scope','create','drill'].includes(a)){lastFocus=el;if(a==='preview'){const t=TASKS.find(t=>t.id===el.dataset.task&&t.project===el.dataset.project),r=t?.results.find(r=>r.id===el.dataset.result);preview={kind:'file',fid:el.dataset.file,t,r,pdfPage:1};event('file_preview',{file:el.dataset.file,result:r.id})}else{if(a==='drill'){state.businessPeriod=el.dataset.period;save()}preview={kind:a}}render()}
 if(a==='close'){preview=null;render();restoreFocus()}
 if(a==='pdfnext'||a==='pdfprev'){preview.pdfPage=Math.max(1,Math.min(12,(preview.pdfPage||1)+(a==='pdfnext'?1:-1)));render()}
 if(a==='full'){state.full=!state.full;save();event('fullscreen',{full:state.full});render()}
 if(a==='inbox'){queueFilter='all';queueSelection='';go({mode:'b',page:'queue'})}
 if(a==='queuepick'){queueSelection=el.dataset.id;const x=queueItems().find(x=>x.id===queueSelection);if(x){state.read[x.kind==='result'?'res:'+x.r.id:x.id]=true;event('queue_open',{id:x.id})}render()}
 if(a==='queuefilter'){queueFilter=el.dataset.value;queueSelection='';render()}if(a==='queueback'){queueSelection='';feedback='';render()}
 if(a==='markread'){state.read[el.dataset.id]=el.dataset.read==='1';save();render()}
 if(a==='answer'){const id=el.dataset.id,text=state.drafts['q:'+id]?.trim();if(!text){toast('填写答复后再提交');return}state.answers[id]=text;save();render();toast('模拟答复已记录；未恢复入口继续保留')}
 if(a==='fakecreate'){preview=null;render();toast('创建入口与表单已演示；未写入任何正式工作')}
 if(a==='review'){const {t,r}=current();if(!t||!r)return;const comment=(state.drafts[key(t,r)]||'').trim(),status=el.dataset.status,complete=el.dataset.complete==='1';if(status==='not_accepted'&&!comment){feedback='未接受结果请填写原因。意见草稿保持。';render();return}if(['error','loading'].includes(state.scenario)){feedback='当前结果读取未完成，办理暂不可提交。意见草稿保持。';render();return}if(state.scenario==='conflict'){feedback='结果或验收条件已变化（模拟冲突）。意见草稿保持，请核对最新版本。';render();return}if(status==='accepted'&&r.revision!==t.criteria){feedback='结果按旧条件提交：接受被拒绝。请按当前 v2 要求补交新结果，意见草稿保持。';render();return}if(status==='accepted'&&state.scenario==='missing'){feedback='文件证据不可访问（模拟）。接受被拒绝，意见草稿保持。';render();return}state.reviews[key(t,r)]={status,comment,complete};if(complete)state.taskStates[t.id]='done';event('review',{project:t.project,task:t.id,result:r.id,status,complete,mode:route.mode});feedback='已'+(status==='accepted'?'接受':'记录未接受')+' '+r.id.toUpperCase()+(complete?'，工作已完成':'，工作状态保持')+'（模拟）。';if(route.mode==='b'){queueSelection='';render();toast(feedback)}else render()}
});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){if(preview){preview=null;render();restoreFocus()}else if(state.full){state.full=false;save();render()}}if(preview&&ev.key==='Tab'){const controls=[...document.querySelectorAll('.drawer button,.drawer a,.drawer input,.drawer textarea')].filter(x=>!x.disabled),first=controls[0],last=controls.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus()}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus()}}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
if(!location.hash)location.hash='#a/alpha/overview';render();
